import React, { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './style.css'
import ProgramIntelligence from './ProgramIntelligence'
import TeamProfile, { matchingForecast } from './TeamProfile'
import ProgramReportCard from './ProgramReportCard'
import ForecastEvidence from './ForecastEvidence'
import HistoricalResults from './HistoricalResults'
import HistoricalGameCoverage from './HistoricalGameCoverage'
import { destinations, SectionTabs, type View } from './Navigation'
import type { ProfileSection } from './TeamProfile'

type RecruitingResearch = { historical_asof_verified: false; joined_team_seasons: number; scorecard: { evaluated_team_seasons: number; heldout_seasons: number; win_mae: number }; program_recruiting_residuals: { programs: { team: string; heldout_seasons: number; average_wins_above_recruiting_baseline: number }[] } }
type Team = { ranking_explanation?: { wins_contribution: number; rating_contribution: number; tie_break_contribution: number; score: number; scope: string }; rank: number; team: string; rating: number; wins: number; losses: number; projected_wins: number; projected_conference_wins: number; rank_score: number }
type Prediction = { game_id: number; week: number; home: string; away: string; predicted_winner: string; home_margin: number; home_win_probability: number; confidence: string }
type CfpTeam = { team: string; conference: string; most_likely_seed: number | null; average_seed_when_selected: number | null; average_wins: number; wins_p10: number; wins_p90: number; bowl_eligible: number; cfp_field: number; first_round_bye: number; quarterfinal: number; semifinal: number; final: number; national_title: number }
type ConferenceTeam = { team: string; conference_wins: number; conference_losses: number; wins: number; losses: number; rating: number; projected_conference_wins: number; conference_title_odds: number; cfp_odds: number }
type Bracket = { methodology: string; conference_championships?: { conference: string; first: string; second: string; projected_champion: string }[]; seeds: { seed: number; team: string; conference: string; bid: string; bye: boolean }[]; first_round: { home_seed: number; away_seed: number; home: string; away: string }[] }
type ScheduleGame = { game_id: number; week: number; home: string; away: string; neutral_site: boolean; completed: boolean; home_score: number | null; away_score: number | null }
type Performance = { actual_wins: number; expected_wins: number; games_with_forecasts: number; wins_above_expected: number | null }
type HistoricalBacktest = { games: number; evaluation_scope: string; model: { winner_accuracy: number; brier_score: number; log_loss: number }; preseason_baseline: { winner_accuracy: number; brier_score: number; log_loss: number }; improvement_vs_preseason: { winner_accuracy_percentage_points: number; brier_score_reduction: number; log_loss_reduction: number }; weekly_coverage: { week: number; games: number }[]; weekly_diagnostics?: { week: number; games: number; model_brier: number; baseline_brier: number; model_winner_accuracy: number; baseline_winner_accuracy: number }[]; matchup_diagnostics?: Record<'fbs_fbs' | 'fbs_fcs', { games: number; model: { winner_accuracy: number; brier_score: number; log_loss: number } | null; preseason_baseline: { winner_accuracy: number; brier_score: number; log_loss: number } | null }> }
type MultiSeasonResearch = { type: string; disclaimer: string; fcs_policy: string; overall: { games: number; accuracy: number; brier: number; logloss: number }; by_season: Record<string, { games: number; accuracy: number; brier: number; logloss: number }> }
type PollSnapshot = { season: number; week: number; source: string; cfp_top25?: { team: string; rank: number }[]; cfp_published_at?: string; cfp_week?: number; cfp_source?: string; ap_top25: { team: string; rank: number }[]; coaches_top25: { team: string; rank: number }[] }
type Report = { model_metadata?: { model_id: string; model_status: string; prediction_scale: number; home_field_advantage: number; historical_study: string }; prediction_accuracy?: { neutral_baseline?: { games: number; winner_accuracy: number | null; brier_score: number | null; log_loss: number | null; description: string }; games_evaluated: number; eligible_completed_games?: number; forecast_coverage?: number | null; correct_winners: number; winner_accuracy: number | null; brier_score: number | null; log_loss?: number | null; margin_mae?: number | null; margin_games?: number; calibration?: { range: string; games: number; mean_predicted: number | null; actual_home_win_rate: number | null }[]; weekly_scorecard?: { week: number; games_evaluated: number; correct_winners: number; winner_accuracy: number; brier_score: number }[] }; performance?: Record<string, Performance>; schedule?: ScheduleGame[]; projected_bracket?: Bracket; cfp?: { simulations: number; methodology: string; teams: CfpTeam[] }; conference_standings?: Record<string, ConferenceTeam[]>; conference_strength?: { conference: string; teams: number; average_rating: number; best_team: string }[]; season: number; source?: string; retrieved_at?: string | null; data_changed_at?: string | null; summary: { teams: number; completed_games: number; upcoming_games: number }; rankings: Team[]; predictions: Prediction[] }

const pct = (p: number) => (p * 100).toFixed(1) + '%'
const num = (n: number) => n.toFixed(2)
// Same rating-gap logistic function and home advantage as the Python prediction model.
const hypothetical = (home: Team, away: Team, neutral: boolean, scale = 18, homeEdge = 3) => {
  const margin = home.rating - away.rating + (neutral ? 0 : homeEdge)
  const homeProbability = 1 / (1 + Math.pow(10, -margin / scale))
  const certainty = Math.max(homeProbability, 1 - homeProbability)
  const confidence = certainty > .8 ? 'Strong' : certainty > .65 ? 'Likely' : certainty > .55 ? 'Lean' : 'Toss-up'
  return { margin, homeProbability, winner: homeProbability >= .5 ? home.team : away.team, confidence }
}

function App() {
  const [installPrompt, setInstallPrompt] = useState<{ prompt: () => Promise<void>; userChoice: Promise<{ outcome: string }> } | null>(null)
  const [installed, setInstalled] = useState(false)
  useEffect(() => {
    const onPrompt = (event: Event) => {
      event.preventDefault()
      setInstallPrompt(event as Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: string }> })
    }
    const onInstalled = () => { setInstalled(true); setInstallPrompt(null) }
    window.addEventListener('beforeinstallprompt', onPrompt)
    window.addEventListener('appinstalled', onInstalled)
    setInstalled(window.matchMedia('(display-mode: standalone)').matches || ('standalone' in navigator && Boolean((navigator as Navigator & { standalone?: boolean }).standalone)))
    return () => {
      window.removeEventListener('beforeinstallprompt', onPrompt)
      window.removeEventListener('appinstalled', onInstalled)
    }
  }, [])
  const [report, setReport] = useState<Report | null>(null)
  const [recruitingResearch, setRecruitingResearch] = useState<RecruitingResearch | null>(null)
  const [historicalBacktest, setHistoricalBacktest] = useState<HistoricalBacktest | null>(null)
  const [multiSeasonResearch, setMultiSeasonResearch] = useState<MultiSeasonResearch | null>(null)
  const [pollSnapshot, setPollSnapshot] = useState<PollSnapshot | null>(null)
  const [pollUnavailable, setPollUnavailable] = useState(false)
  const [error, setError] = useState('')
  const [refreshAttempt, setRefreshAttempt] = useState(0)
  const [appUpdateReady, setAppUpdateReady] = useState(false)
  const [offline, setOffline] = useState(!navigator.onLine)
  const [pollSort, setPollSort] = useState<'model' | 'ap' | 'coaches' | 'cfp'>('model')
  const [tab, setCurrentView] = useState<View>('home')
  const [profileSection, setProfileSection] = useState<ProfileSection>('overview')
  const setTab = (view: View) => {
    if (view === 'profile') setProfileSection('overview')
    if (view === 'ap' || view === 'coaches') setPollSort(view)
    setCurrentView(view)
  }
  const activeDestination = destinations.find(destination => destination.views.some(view => view.id === tab))!
  const [favorites, setFavorites] = useState<(string | null)[]>(() => {
    try { const saved = JSON.parse(localStorage.getItem('cfba-favorites-v1') || '[]'); return Array.isArray(saved) ? Array.from({length: 3}, (_, i) => typeof saved[i] === 'string' ? saved[i] as string : null) : [null, null, null] } catch { return [null, null, null] }
  })
  const [favoritePicker, setFavoritePicker] = useState('')
  const [shareNotice, setShareNotice] = useState('')
  useEffect(() => { try { localStorage.setItem('cfba-favorites-v1', JSON.stringify(favorites)) } catch { /* Private browsing may block storage. */ } }, [favorites])
  const [search, setSearch] = useState('')
  const [showTeamSuggestions, setShowTeamSuggestions] = useState(false)
  const [week, setWeek] = useState('next')
  const [conference, setConference] = useState('Big 12')
  const openComparison = (team: string) => { setHomeTeam(team); setAwayTeam(''); setVenue('neutral'); setTab('compare') }
  const [homeTeam, setHomeTeam] = useState('')
  const [awayTeam, setAwayTeam] = useState('')
  const [scheduleTeam, setScheduleTeam] = useState('')
  const [venue, setVenue] = useState<'home' | 'away' | 'neutral'>('home')

  useEffect(() => {
    if (!('serviceWorker' in navigator)) return
    let active = true
    const observe = (registration: ServiceWorkerRegistration) => {
      if (registration.waiting && navigator.serviceWorker.controller && active) setAppUpdateReady(true)
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing
        worker?.addEventListener('statechange', () => {
          if (worker.state === 'installed' && navigator.serviceWorker.controller && active) setAppUpdateReady(true)
        })
      })
    }
    navigator.serviceWorker.getRegistration(import.meta.env.BASE_URL).then(registration => {
      if (registration && active) observe(registration)
    }).catch(() => { /* Service worker is optional. */ })
    return () => { active = false }
  }, [])

  useEffect(() => {
    const sync = () => setOffline(!navigator.onLine)
    window.addEventListener('online', sync)
    window.addEventListener('offline', sync)
    return () => { window.removeEventListener('online', sync); window.removeEventListener('offline', sync) }
  }, [])

  useEffect(() => {
    const controller = new AbortController()
    setError('')
    fetch(import.meta.env.BASE_URL + 'season-report.json', { cache: 'no-store', signal: controller.signal })
      .then(r => { if (!r.ok || !r.headers.get('content-type')?.includes('json')) throw new Error('No valid published season report is available yet.'); return r.json() })
      .then((data: Report) => {
        if (!Number.isInteger(data.season) || !Array.isArray(data.rankings) || !Array.isArray(data.predictions)) throw new Error('Invalid report format')
        if (controller.signal.aborted) return
        setReport(data)
        setError('')
      })
      .catch(e => { if (!controller.signal.aborted) setError(String(e.message || e)) })
    return () => controller.abort()
  }, [refreshAttempt])

  useEffect(() => {
    fetch(import.meta.env.BASE_URL + 'v34-recruiting-research.json', { cache: 'no-store' })
      .then(r => { if (!r.ok) throw new Error('Research unavailable'); return r.json() })
      .then((data: RecruitingResearch) => {
        if (data.historical_asof_verified === false && Array.isArray(data.program_recruiting_residuals?.programs) && data.scorecard?.evaluated_team_seasons > 0) setRecruitingResearch(data)
      })
      .catch(() => { /* Optional research, never block live rankings. */ })
  }, [])

  useEffect(() => {
    fetch(import.meta.env.BASE_URL + 'historical-backtest.json', { cache: 'no-store' })
      .then(r => { if (!r.ok) throw new Error('Historical backtest unavailable'); return r.json() })
      .then((data: HistoricalBacktest) => {
        if (data.games > 0 && data.model && data.preseason_baseline && data.improvement_vs_preseason) setHistoricalBacktest(data)
      })
      .catch(() => { /* Optional historical evidence; do not block the live dashboard. */ })
  }, [])

  useEffect(() => {
    fetch(import.meta.env.BASE_URL + 'poll-snapshot.json', { cache: 'no-store' })
      .then(r => { if (!r.ok) throw new Error('Poll snapshot unavailable'); return r.json() })
      .then((data: PollSnapshot) => {
        if (Number.isInteger(data.season) && data.season >= 2026 && Number.isInteger(data.week) &&
            Array.isArray(data.ap_top25) && Array.isArray(data.coaches_top25) &&
            data.ap_top25.length > 0 && data.coaches_top25.length > 0 && data.source &&
            (!data.cfp_top25?.length || (typeof data.cfp_published_at === 'string' &&
              /^\d{4}-\d{2}-\d{2}$/.test(data.cfp_published_at) &&
              !Number.isNaN(Date.parse(data.cfp_published_at)) &&
              data.cfp_published_at.startsWith(String(data.season) + '-'))) &&
            [data.ap_top25, data.coaches_top25, ...(data.cfp_top25 ? [data.cfp_top25] : [])].every(poll =>
              Array.isArray(poll) && poll.length <= 25 &&
              poll.every(row => typeof row.team === 'string' && row.team.trim().length > 0 &&
                Number.isInteger(row.rank) && row.rank >= 1 && row.rank <= 25) &&
              new Set(poll.map(row => row.team)).size === poll.length &&
              new Set(poll.map(row => row.rank)).size === poll.length)) setPollSnapshot(data)
        else setPollUnavailable(true)
      })
      .catch(() => setPollUnavailable(true))
  }, [])

  useEffect(() => {
    fetch(import.meta.env.BASE_URL + 'v2-research-summary.json', { cache: 'no-store' })
      .then(r => { if (!r.ok) throw new Error('Research summary unavailable'); return r.json() })
      .then((data: MultiSeasonResearch) => {
        if (data.type === 'retrospective_walk_forward_baseline' &&
            data.overall?.games > 0 && Number.isFinite(data.overall.accuracy) &&
            Number.isFinite(data.overall.brier) && Number.isFinite(data.overall.logloss) &&
            data.disclaimer && data.fcs_policy && data.by_season) setMultiSeasonResearch(data)
      })
      .catch(() => { /* Optional V2 research; preserve V1 dashboard. */ })
  }, [])

  const sharePrediction = async (p: Prediction) => {
    const probability = p.predicted_winner === p.home ? p.home_win_probability : 1 - p.home_win_probability
    const asOf = report?.retrieved_at ? `Data retrieved: ${report.retrieved_at}` : 'Data retrieval time unavailable'; const caveat = report?.source?.includes('DEMO') ? 'Demonstration data, not live results.' : ''
    const message = `College Football Analytics · Week ${p.week}: ${p.away} at ${p.home}. Model pick: ${p.predicted_winner} (${pct(probability)} win probability). ${asOf}. ${caveat} ${window.location.origin + import.meta.env.BASE_URL}`
    try {
      if (navigator.share) { await navigator.share({ title: 'College Football Analytics prediction', text: message }); setShareNotice('Prediction shared.'); return }
      if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(message); setShareNotice('Prediction copied to clipboard.'); return }
      setShareNotice('Sharing is unavailable in this browser.')
    } catch (error) { if ((error as Error).name !== 'AbortError') setShareNotice('Could not share this prediction.'); }
  }
  const upcomingGameIds = useMemo(() => new Set((report?.schedule || []).filter(g => !g.completed).map(g => g.game_id)), [report])
  const futurePredictions = useMemo(() => (report?.predictions || []).filter(p => upcomingGameIds.has(p.game_id)), [report, upcomingGameIds])
  const weeks = useMemo(() => [...new Set(futurePredictions.map(p => p.week))].sort((a, b) => a - b), [futurePredictions])
  const nextWeek = weeks[0]
  const predictionTeamNames = useMemo(() => [...new Set(futurePredictions.flatMap(p => [p.home, p.away]))].sort((a, b) => a.localeCompare(b)), [futurePredictions])
  const teamSuggestions = useMemo(() => search.trim() ? predictionTeamNames.filter(name => name.toLowerCase().includes(search.trim().toLowerCase())).slice(0, 8) : [], [predictionTeamNames, search])
  const teams = useMemo(() => (report?.rankings || []).filter(t => t.team.toLowerCase().includes(search.toLowerCase())), [report, search])
  // A team search must work across the remaining schedule, regardless of the selected week.
  const predictions = useMemo(() => futurePredictions.filter(p =>
    (search.trim() !== '' || week === 'all' || p.week === Number(week === 'next' ? nextWeek : week)) &&
    [p.home, p.away].some(team => team.toLowerCase().includes(search.trim().toLowerCase()))
  ), [futurePredictions, week, nextWeek, search])
  const sortedPredictions = [...predictions].sort((a, b) => a.week - b.week || Math.abs(b.home_win_probability - .5) - Math.abs(a.home_win_probability - .5))
  const isDemo = !!report?.source?.includes('DEMO')
  const retrievedTime = report?.retrieved_at ? Date.parse(report.retrieved_at) : NaN
  const freshnessUnknown = !!report && !isDemo && !Number.isFinite(retrievedTime)
  const staleData = !!report && !isDemo && Number.isFinite(retrievedTime) &&
    (retrievedTime > Date.now() + 60 * 60 * 1000 || Date.now() - retrievedTime > 72 * 60 * 60 * 1000)

  const conferences = Object.keys(report?.conference_standings || {}).sort()
  const selectedConference = conferences.includes(conference) ? conference : (conferences[0] || '')
  const conferenceRows = (report?.conference_standings?.[selectedConference] || []).filter(t => t.team.toLowerCase().includes(search.toLowerCase()))
  const rankedName = (name: string) => { const rank = report?.rankings.find(t => t.team === name)?.rank; return `${rank ? '#' + rank + ' ' : ''}${name}` }
  const bracketByTeam = new Map((report?.projected_bracket?.seeds || []).map(s => [s.team, s]))
  const cfpRows = (report?.cfp?.teams || []).filter(t => t.team.toLowerCase().includes(search.toLowerCase()))
  const sortedTeams = [...(report?.rankings || [])].sort((a, b) => a.team.localeCompare(b.team))
  const selectedHome = report?.rankings.find(t => t.team === homeTeam)
  const selectedAway = report?.rankings.find(t => t.team === awayTeam)
  const actualHome = venue === 'away' ? selectedAway : selectedHome
  const actualAway = venue === 'away' ? selectedHome : selectedAway
  const selectedScheduleTeam = scheduleTeam || report?.rankings[0]?.team || ''
  const scheduleRecord = report?.rankings.find(t => t.team === selectedScheduleTeam)
  const performance = report?.performance?.[selectedScheduleTeam]
  const expectationLeaderboard = Object.entries(report?.performance || {})
    .filter(([, row]) => row.games_with_forecasts >= 3 && row.wins_above_expected !== null)
    .sort((a, b) => (b[1].wins_above_expected ?? 0) - (a[1].wins_above_expected ?? 0))
  const teamSchedule = (report?.schedule || []).filter(g => g.home === selectedScheduleTeam || g.away === selectedScheduleTeam).sort((a,b) => a.week - b.week || a.game_id - b.game_id)
  const matchup = actualHome && actualAway && homeTeam !== awayTeam ? hypothetical(actualHome, actualAway, venue === 'neutral', report?.model_metadata?.prediction_scale, report?.model_metadata?.home_field_advantage) : null
  const schoolSchedule = report && <section className="matchup-panel"><h3>Full Season Schedule and Model Outlook</h3><p>Completed games show final scores. Remaining games show model forecasts based on the current published ratings.</p>{scheduleRecord && <div className="schedule-summary"><div><small>MODEL RANK</small><strong>#{scheduleRecord.rank}</strong></div><div><small>CURRENT RECORD</small><strong>{scheduleRecord.wins}–{scheduleRecord.losses}</strong></div><div><small>PROJECTED WINS</small><strong>{num(scheduleRecord.projected_wins)}</strong></div></div>}<div className="performance-panel"><h3>Performance vs. Expectations</h3>{performance && performance.games_with_forecasts > 0 ? <><div className="schedule-summary"><div><small>ACTUAL WINS (TRACKED)</small><strong>{performance.actual_wins}</strong></div><div><small>EXPECTED WINS (TRACKED)</small><strong>{num(performance.expected_wins)}</strong></div><div><small>WINS ABOVE EXPECTED</small><strong className={(performance.wins_above_expected || 0) >= 0 ? 'overachieving' : 'underachieving'}>{performance.wins_above_expected! > 0 ? '+' : ''}{num(performance.wins_above_expected!)}</strong></div></div><p>{performance.wins_above_expected! > 0.05 ? 'Overachieving' : performance.wins_above_expected! < -0.05 ? 'Underachieving' : 'Near expectations'} · Based on {performance.games_with_forecasts} completed game(s) with archived forecasts, not the full season.</p></> : <p>Not enough archived pregame forecasts yet. Tracking starts as upcoming games are completed; past forecasts are not invented.</p>}</div>{expectationLeaderboard.length > 0 && <section className="expectation-leaders"><h3>Most Above / Below Expectations</h3><p>Only teams with at least three completed games with archived pregame forecasts are eligible.</p><div className="leader-columns"><div><h4>Overachievers</h4>{expectationLeaderboard.filter(([, row]) => (row.wins_above_expected ?? 0) > 0).slice(0, 5).map(([team, row]) => <button key={team} type="button" onClick={() => setScheduleTeam(team)}><span>{team}</span><strong className="overachieving">+{num(row.wins_above_expected!)}</strong></button>)}</div><div><h4>Underachievers</h4>{[...expectationLeaderboard].reverse().filter(([, row]) => (row.wins_above_expected ?? 0) < 0).slice(0, 5).map(([team, row]) => <button key={team} type="button" onClick={() => setScheduleTeam(team)}><span>{team}</span><strong className="underachieving">{num(row.wins_above_expected!)}</strong></button>)}</div></div></section>}{!report.schedule ? <p className="notice">The published report does not yet include full schedules. Refresh the season report to enable this view.</p> : <div className="table-wrap"><table><thead><tr><th scope="col">Opponent</th><th scope="col">Week</th><th scope="col">Location</th><th scope="col">Result / prediction</th><th scope="col">Win chance</th><th scope="col">Margin</th></tr></thead><tbody>{teamSchedule.map(g => { const isHome = g.home === selectedScheduleTeam; const opponent = isHome ? g.away : g.home; const location = g.neutral_site ? 'Neutral' : isHome ? 'Home' : 'Away'; const p = matchingForecast(report.predictions, g); const teamProb = p ? (isHome ? p.home_win_probability : 1 - p.home_win_probability) : null; const teamMargin = p?.home_margin != null ? (isHome ? p.home_margin : -p.home_margin) : null; const scored = g.completed && g.home_score !== null && g.away_score !== null && Number.isFinite(g.home_score) && Number.isFinite(g.away_score); const won = scored && (isHome ? g.home_score! > g.away_score! : g.away_score! > g.home_score!); return <tr key={g.game_id}><td className="team">{opponent}</td><td>{g.week}</td><td>{location}</td><td className="emphasis">{g.completed ? scored ? <>{won ? 'W' : 'L'} {isHome ? g.home_score : g.away_score}–{isHome ? g.away_score : g.home_score}</> : 'Final score unavailable' : p ? <>{p.predicted_winner === selectedScheduleTeam ? 'Projected W' : 'Projected L'}</> : 'Prediction unavailable'}</td><td>{g.completed ? 'Final' : teamProb === null ? '—' : pct(teamProb)}</td><td>{g.completed ? '—' : teamMargin === null ? '—' : (teamMargin > 0 ? '+' : '') + num(teamMargin)}</td></tr>})}</tbody></table>{teamSchedule.length === 0 && <p>No games found for this school in the current feed.</p>}</div>}</section>
  return <main className="app">{offline && <div role="status" className="offline-warning">You are offline. Current scores, rankings, and predictions cannot be refreshed. Any displayed report may be outdated.</div>}
    <header className="brand-header"><img className="brand-logo" src={`${import.meta.env.BASE_URL}icons/icon-512.png`} alt="College Football Analytics collegiate logo" width="112" height="112" /><div className="brand-copy"><div className="eyebrow">COLLEGE FOOTBALL · SEASON INTELLIGENCE</div><h1>College Football <span>Analytics</span></h1><p>Rankings, predictions and playoff outlooks—backed by data.</p></div></header>
    <div className="app-utilities"><details className="install-guide" aria-label="About, privacy and getting started"><summary>About &amp; privacy</summary><div className="install-guide-content"><p><strong>Start here:</strong> This Week highlights upcoming games. Use Home for games, Rankings for model and poll comparisons, Teams for school analysis, Playoffs for postseason races, and Research for evidence and methods. Save up to three schools under My Teams.</p><p><strong>Your saved teams:</strong> Favorites are stored only in this browser on this device. No account or cross-device synchronization is provided. Clearing site data, private browsing, or browser storage restrictions can remove saved teams. Other browser profiles have separate selections.</p><p><strong>Data and forecasts:</strong> Published report timestamps and freshness warnings appear above the dashboard. Predictions and playoff odds are model estimates, not guarantees; see Research &amp; Data for methods, evidence, and limitations. Historical metrics without verified sources are not published.</p><p><strong>Privacy:</strong> Favorite selections remain in your browser storage and are not sent to an account service by this feature. The app retrieves published football data and may be subject to ordinary hosting and network logs; do not treat browser storage as a secure backup.</p><p><strong>Feedback:</strong> Report issues or suggest improvements through <a href="https://github.com/landrumc16/College-Football-Analytics/issues/new" target="_blank" rel="noopener noreferrer">the project issue form</a>. GitHub may require sign-in; avoid including personal information in public issues.</p></div></details>
    {!installed && <details className="install-guide"><summary>Install app</summary><div className="install-guide-content"><p>Get one-tap access from your home screen—no app store needed.</p>{installPrompt && <button type="button" onClick={async () => { const prompt = installPrompt; setInstallPrompt(null); await prompt.prompt(); await prompt.userChoice }}>Install App</button>}<p><strong>iPhone:</strong> Open this page in Safari, tap Share, then choose <strong>Add to Home Screen</strong> and tap Add.</p><p><strong>Android:</strong> Open this page in Chrome, tap the three-dot menu, then choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p></div></details>}
    </div>
    {appUpdateReady && <section className="notice" role="status"><strong>App update available</strong><p>A newer interface is ready. Reload to use it; live football data is never served from the offline cache.</p><button type="button" onClick={() => window.location.reload()}>Reload app</button></section>}
    {error ? <section className="notice"><strong>Waiting for live data</strong><p>{error}</p><p>Check your connection and retry. If the report remains unavailable, the published data may need a refresh.</p><button type="button" onClick={() => setRefreshAttempt(n => n + 1)}>Retry loading data</button></section> : null}
    {report && <>
      {report.source?.includes("DEMO") && <section className="notice"><strong>Historical demonstration — not live rankings</strong><p>This view uses the frozen 2026 Week 7 workbook baseline. Live rankings will replace it after the CFBD refresh is verified.</p></section>}
      {(freshnessUnknown || staleData) && <section className="notice"><strong>Data freshness warning</strong><p>{freshnessUnknown ? 'This report has no valid retrieval timestamp; live-data freshness cannot be verified.' : 'This report was retrieved more than 72 hours ago (or has a future timestamp). Rankings and forecasts may be outdated.'}</p></section>}
      <p className="data-timestamp" role="status">{isDemo ? 'Historical Demo Data' : report.retrieved_at && Number.isFinite(retrievedTime) ? `Data Updated: ${new Date(retrievedTime).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })}` : 'Data Update Time Unavailable'} · Source: {isDemo ? 'Frozen Historical Fixture' : 'CollegeFootballData'}</p>


    <nav className="primary-navigation" aria-label="Main navigation">
      {destinations.map(destination => <button type="button" key={destination.id}
        aria-current={activeDestination.id === destination.id ? 'page' : undefined}
        onClick={() => { if (activeDestination.id !== destination.id) { setSearch(''); setTab(destination.views[0].id) } }}>{destination.label}</button>)}
    </nav>
    <SectionTabs label={`${activeDestination.label} sections`} items={activeDestination.views} value={tab}
      panelId="dashboard-panel" onChange={value => { setSearch(''); setTab(value as View) }} />
    <div id="dashboard-panel" role="tabpanel" aria-labelledby={`dashboard-panel-${tab}`}>
    {tab === 'rankings' && <h2>Model Rankings</h2>}
    {tab === 'conferences' && <h2>Conference Championship Races</h2>}
    <div className="toolbar">{tab === 'rankings' && <input aria-label="Search teams" placeholder="Search teams…" value={search} onChange={e => setSearch(e.target.value)}/>}
      {tab === 'predictions' && <div className="team-search"><input aria-label="Search teams" aria-autocomplete="list" aria-controls="team-search-suggestions" aria-expanded={showTeamSuggestions && teamSuggestions.length > 0} autoComplete="off" placeholder="Start typing a school…" value={search} onFocus={() => setShowTeamSuggestions(true)} onChange={e => { setSearch(e.target.value); setShowTeamSuggestions(true) }} onKeyDown={e => { if (e.key === 'Escape') setShowTeamSuggestions(false); if (e.key === 'Enter' && teamSuggestions.length) { setSearch(teamSuggestions[0]); setShowTeamSuggestions(false) } }}/>{showTeamSuggestions && teamSuggestions.length > 0 && <div id="team-search-suggestions" className="team-suggestions" role="listbox" aria-label="Suggested schools">{teamSuggestions.map(name => <button type="button" role="option" aria-selected={search === name} key={name} onClick={() => { setSearch(name); setShowTeamSuggestions(false) }}>{name}</button>)}</div>}</div>} {tab === 'conferences' && <select aria-label="Select conference" value={selectedConference} onChange={e => setConference(e.target.value)}>{conferences.map(name => <option key={name} value={name}>{name}</option>)}</select>}{tab === 'predictions' && <select aria-label="Filter by week" value={week} onChange={e => setWeek(e.target.value)}><option value="next">Next Week{nextWeek != null ? ` (${nextWeek})` : ""}</option><option value="all">All Remaining Weeks</option>{weeks.map(w => <option key={w} value={w}>Week {w}</option>)}</select>}</div>
      {report && tab === 'home' && <section className="weekly-home" aria-label="This Week">
      <h2>This Week</h2><p>Season {report.season} · Game previews and playoff projections from the latest published report. {isDemo ? 'Demonstration data — not live results.' : staleData ? 'Data may be stale; check the retrieval timestamp.' : freshnessUnknown ? 'Data freshness cannot be verified.' : ''}</p>
      <section className="favorite-panel">
        <div className="weekly-section-heading"><h3>My Teams</h3><span>{favorites.filter(Boolean).length} of 3 selected</span></div>
        <div className="favorite-grid">
          {favorites.map((name, slot) => {
            if (!name) return null
            const team = report.rankings.find(t => t.team === name)
            const game = futurePredictions.filter(p => p.home === name || p.away === name).sort((a,b) => a.week-b.week)[0]
            const probability = game ? (game.home === name ? game.home_win_probability : 1-game.home_win_probability) : null
            return <article key={slot} className="favorite-card">
              <div className="weekly-section-heading"><strong>{name}</strong><button type="button" aria-label={`Remove ${name} from favorites`} onClick={() => setFavorites(old => old.map((x, i) => i === slot ? null : x))}>×</button></div>
              <p>{team ? `#${team.rank} · ${team.wins}–${team.losses}` : 'Ranking and record unavailable'}</p>
              <p>{game ? `Week ${game.week}: ${game.home === name ? 'vs' : 'at'} ${game.home === name ? game.away : game.home}` : 'No upcoming game listed'}</p>
              {probability !== null && <strong>{pct(probability)} win chance</strong>}
              <div className="matchup-actions"><button type="button" onClick={() => {setScheduleTeam(name);setTab('profile')}}>Team profile</button><button type="button" onClick={() => openComparison(name)}>Compare</button><button type="button" onClick={() => {setScheduleTeam(name);setTab('profile');setProfileSection('schedule')}}>View schedule</button></div>
            </article>
          })}
          {favorites.some(x => !x) && <details className="favorite-add">
            <summary>+ Add Team</summary>
            <div className="favorite-add-content">
              <label htmlFor="favorite-team-search">Find a school</label>
              <input id="favorite-team-search" list="favorite-team-options" aria-label="Add favorite team" placeholder="Search for a school…" value={favoritePicker} onChange={e => setFavoritePicker(e.target.value)}/>
              <datalist id="favorite-team-options">{report.rankings.filter(t => !favorites.includes(t.team)).map(t => <option key={t.team} value={t.team}/>)}</datalist>
              <button type="button" disabled={!report.rankings.some(t => t.team === favoritePicker && !favorites.includes(t.team))} onClick={() => {setFavorites(old => {const next = [...old]; const empty = next.findIndex(x => !x); if (empty >= 0 && !next.includes(favoritePicker)) next[empty] = favoritePicker; return next});setFavoritePicker('')}}>Save Team</button>
            </div>
          </details>}
        </div>
      </section>
      <div className="weekly-home-grid">
        <section><h3>Featured Games</h3><p>Top-ranked teams playing this week. # numbers are Our Model Rankings.</p>{futurePredictions.filter(p => p.week === nextWeek).sort((a,b) => Math.min(report.rankings.find(t=>t.team===a.home)?.rank ?? 999,report.rankings.find(t=>t.team===a.away)?.rank ?? 999)-Math.min(report.rankings.find(t=>t.team===b.home)?.rank ?? 999,report.rankings.find(t=>t.team===b.away)?.rank ?? 999)).slice(0,5).map(p => <button key={p.game_id} type="button" className="weekly-game" onClick={() => {setSearch(p.home);setWeek(String(p.week));setTab('predictions')}}><strong>{rankedName(p.away)} at {rankedName(p.home)}</strong><span>Week {p.week} · {p.predicted_winner} {pct(Math.max(p.home_win_probability,1-p.home_win_probability))} to win</span></button>)}{!futurePredictions.some(p => p.week === nextWeek) && <p>No upcoming games in the published report.</p>}</section>
        <section><h3>Upset Watch</h3><p>Games where our model favors a lower-ranked team. # numbers are Our Model Rankings.</p>{futurePredictions.filter(p => p.week === nextWeek && (() => {const h=report.rankings.find(t=>t.team===p.home),a=report.rankings.find(t=>t.team===p.away);return h && a && ((p.predicted_winner===p.home && h.rank>a.rank)||(p.predicted_winner===p.away && a.rank>h.rank))})()).slice(0,3).map(p => <button key={p.game_id} type="button" className="weekly-game" onClick={() => {setSearch(p.home);setWeek(String(p.week));setTab('predictions')}}>{rankedName(p.predicted_winner)} over {rankedName(p.predicted_winner===p.home?p.away:p.home)}</button>)}{!futurePredictions.some(p => p.week === nextWeek && (()=>{const h=report.rankings.find(t=>t.team===p.home),a=report.rankings.find(t=>t.team===p.away);return h&&a&&((p.predicted_winner===p.home&&h.rank>a.rank)||(p.predicted_winner===p.away&&a.rank>h.rank))})()) && <p>No model-favored ranking upsets this week.</p>}
        </section><section><h3>Games That Matter</h3><p>Upcoming games featuring teams in Our Model Top 25. # numbers are Our Model Rankings; ranking movement is not predicted.</p>{futurePredictions.filter(p => p.week === nextWeek).map(p => { const homeRank=report.rankings.find(t=>t.team===p.home)?.rank; const awayRank=report.rankings.find(t=>t.team===p.away)?.rank; const best=Math.min(homeRank ?? 999,awayRank ?? 999); const bothRanked=(homeRank ?? 999)<=25 && (awayRank ?? 999)<=25; return {p,homeRank,awayRank,best,bothRanked} }).filter(x=>x.best<=25).sort((a,b)=>Number(b.bothRanked)-Number(a.bothRanked)||a.best-b.best).slice(0,4).map(({p,homeRank,awayRank,bothRanked})=><button key={p.game_id} type="button" className="weekly-game" onClick={()=>{setSearch(p.home);setWeek(String(p.week));setTab('predictions')}}><strong>{awayRank && awayRank<=25 ? '#'+awayRank+' ' : ''}{p.away} at {homeRank && homeRank<=25 ? '#'+homeRank+' ' : ''}{p.home}</strong><span>{bothRanked ? 'Top-25 matchup' : 'Top-25 team in action'} · Week {p.week} · {pct(Math.max(p.home_win_probability,1-p.home_win_probability))} for {p.predicted_winner}</span></button>)}{!futurePredictions.some(p=>p.week===nextWeek && ((report.rankings.find(t=>t.team===p.home)?.rank ?? 999)<=25 || (report.rankings.find(t=>t.team===p.away)?.rank ?? 999)<=25)) && <p>No upcoming top-25 matchups in the published report.</p>}</section>
      <section className="playoff-snapshot"><h3>Playoff Snapshot</h3><p>Leading seeds in the published model projection.</p>
        {report.projected_bracket?.seeds.length ? <ol className="playoff-shortlist">{[...report.projected_bracket.seeds].sort((a,b) => a.seed-b.seed).slice(0,4).map(seed => <li key={seed.seed}>#{seed.seed} {seed.team}</li>)}</ol> : <p>Playoff projections are unavailable in this report.</p>}
        <button type="button" onClick={() => setTab('cfp')}>View playoff projections</button>
      </section>
      </div></section>}
      {shareNotice && <p role="status" className="share-notice">{shareNotice}</p>}
      {(['research', 'history', 'methods', 'sources', 'validation'] as string[]).includes(tab) && <section className="research-page">
      <h2>{activeDestination.views.find(view => view.id === tab)?.label}</h2>
      <p>Methods, evidence and source details behind the dashboard. Retrospective results are not verified pregame predictions.</p>
      {tab === 'research' && <><ForecastEvidence />{report.prediction_accuracy && <section className="accuracy-summary" aria-label="Historical Prediction Accuracy"><strong>Prediction Track Record</strong><p>{report.prediction_accuracy.games_evaluated > 0 && report.prediction_accuracy.winner_accuracy !== null ? `${pct(report.prediction_accuracy.winner_accuracy)} correct winners across ${report.prediction_accuracy.games_evaluated} archived pregame forecasts · Brier Score: ${report.prediction_accuracy.brier_score?.toFixed(3) ?? 'N/A'}` : 'Awaiting completed games with archived pregame forecasts. No historical accuracy is claimed yet.'}</p>{report.prediction_accuracy.games_evaluated > 0 && <p>Log loss: {report.prediction_accuracy.log_loss?.toFixed(3) ?? "N/A"} · Margin MAE: {report.prediction_accuracy.margin_mae?.toFixed(1) ?? "N/A"} points ({report.prediction_accuracy.margin_games ?? 0} games)</p>}{report.prediction_accuracy.neutral_baseline && report.prediction_accuracy.games_evaluated > 0 && <p>Same-game 50/50 baseline ({report.prediction_accuracy.neutral_baseline.games} games): accuracy {report.prediction_accuracy.neutral_baseline.winner_accuracy == null ? "N/A" : pct(report.prediction_accuracy.neutral_baseline.winner_accuracy)} · Brier {report.prediction_accuracy.neutral_baseline.brier_score?.toFixed(3) ?? "N/A"} · log loss {report.prediction_accuracy.neutral_baseline.log_loss?.toFixed(3) ?? "N/A"}. This is a neutral reference, not a competing prediction model.</p>}{report.prediction_accuracy.calibration?.some(b => b.games > 0) && <p>Calibration (predicted vs. actual home wins): {report.prediction_accuracy.calibration.filter(b => b.games > 0).map(b => `${b.range}: ${pct(b.mean_predicted ?? 0)} / ${pct(b.actual_home_win_rate ?? 0)} (n=${b.games})`).join(" · ")}</p>}{report.prediction_accuracy.weekly_scorecard && report.prediction_accuracy.weekly_scorecard.length > 0 && <p>Weekly verified forecasts: {report.prediction_accuracy.weekly_scorecard.map(w => `Week ${w.week}: ${pct(w.winner_accuracy)} (${w.correct_winners}/${w.games_evaluated}), Brier ${w.brier_score.toFixed(3)}`).join(' · ')}</p>}<small>{report.prediction_accuracy.eligible_completed_games !== undefined ? `Coverage: ${report.prediction_accuracy.games_evaluated} of ${report.prediction_accuracy.eligible_completed_games} eligible completed FBS–FBS games (${report.prediction_accuracy.forecast_coverage === null ? "N/A" : pct(report.prediction_accuracy.forecast_coverage ?? 0)}). ` : ""}Only verified archived pregame forecasts between FBS teams are evaluated; lower Brier, log loss and margin MAE are better. Retrospective studies are separate.</small></section>}
      </>}
      {tab === 'history' && <><details className="research-topic"><summary>Recruiting &amp; Program Development</summary>{recruitingResearch && <section className="notice"><h2>Recruiting vs. Results · Historical Research</h2><p>Retrospective recruiting-only baseline, not verified pregame forecasts or causal coaching/development rankings. {recruitingResearch.scorecard.evaluated_team_seasons} held-out team-seasons across {recruitingResearch.scorecard.heldout_seasons} seasons; average wins error {recruitingResearch.scorecard.win_mae.toFixed(2)}.</p><div className="table-wrap"><table><thead><tr><th>Program</th><th>Held-out seasons</th><th>Avg. wins above recruiting baseline</th></tr></thead><tbody>{recruitingResearch.program_recruiting_residuals.programs.slice(0,15).map(p => <tr key={p.team}><td className="team">{p.team}</td><td>{p.heldout_seasons}</td><td>{p.average_wins_above_recruiting_baseline > 0 ? '+' : ''}{p.average_wins_above_recruiting_baseline.toFixed(2)}</td></tr>)}</tbody></table></div></section>}
      </details><details className="research-topic"><summary>Multi-season Historical Research</summary>{multiSeasonResearch && <section className="accuracy-summary" aria-label="V2 Multi-season Research"><strong>V2 Research · 2022–2025 Retrospective Elo</strong><p>{multiSeasonResearch.overall.games.toLocaleString()} FBS-versus-FBS games · {pct(multiSeasonResearch.overall.accuracy)} winner accuracy · Brier {num(multiSeasonResearch.overall.brier)} · Log loss {num(multiSeasonResearch.overall.logloss)}</p><div className="table-wrap"><table><thead><tr><th>Season</th><th>Games</th><th>Winner accuracy</th><th>Brier</th></tr></thead><tbody>{Object.entries(multiSeasonResearch.by_season).sort(([a], [b]) => a.localeCompare(b)).map(([season, row]) => <tr key={season}><td>{season}</td><td>{row.games}</td><td>{pct(row.accuracy)}</td><td>{num(row.brier)}</td></tr>)}</tbody></table></div><small>{multiSeasonResearch.disclaimer} {multiSeasonResearch.fcs_policy}. This is not a market comparison.</small></section>}
      </details><HistoricalGameCoverage onTeam={team => {setScheduleTeam(team);setTab('profile')}} /></>}
      {tab === 'validation' && <>{historicalBacktest && <section className="accuracy-summary" aria-label="Retrospective Weekly Backtest"><strong>Retrospective Weekly Backtest · Frozen 2026 Data</strong><p>{historicalBacktest.games} completed games evaluated using pre-week model snapshots, including FCS opponents.</p><p>Model: {pct(historicalBacktest.model.winner_accuracy)} winners · Brier {num(historicalBacktest.model.brier_score)} · Log loss {num(historicalBacktest.model.log_loss)}</p><p>Preseason baseline: {pct(historicalBacktest.preseason_baseline.winner_accuracy)} winners · Brier {num(historicalBacktest.preseason_baseline.brier_score)} · Log loss {num(historicalBacktest.preseason_baseline.log_loss)}</p><p>Change versus preseason: {historicalBacktest.improvement_vs_preseason.winner_accuracy_percentage_points.toFixed(1)} percentage points accuracy · {num(historicalBacktest.improvement_vs_preseason.brier_score_reduction)} Brier reduction · {num(historicalBacktest.improvement_vs_preseason.log_loss_reduction)} log-loss reduction</p>{historicalBacktest.matchup_diagnostics && <div className="table-wrap"><table><thead><tr><th>Matchup</th><th>Games</th><th>Model accuracy</th><th>Model Brier</th><th>Preseason Brier</th></tr></thead><tbody>{(['fbs_fbs', 'fbs_fcs'] as const).map(key => { const row = historicalBacktest.matchup_diagnostics?.[key]; return row && <tr key={key}><td>{key === 'fbs_fbs' ? 'FBS vs FBS' : 'FBS vs FCS'}</td><td>{row.games}</td><td>{row.model ? pct(row.model.winner_accuracy) : '—'}</td><td>{row.model ? num(row.model.brier_score) : '—'}</td><td>{row.preseason_baseline ? num(row.preseason_baseline.brier_score) : '—'}</td></tr> })}</tbody></table></div>}{historicalBacktest.weekly_diagnostics && <details><summary>Weekly prediction diagnostics ({historicalBacktest.weekly_diagnostics.length} weeks)</summary><div className="table-wrap"><table><thead><tr><th>Week</th><th>Games</th><th>Model accuracy</th><th>Model Brier</th><th>Preseason Brier</th></tr></thead><tbody>{historicalBacktest.weekly_diagnostics.map(row => <tr key={row.week}><td>{row.week}</td><td>{row.games}</td><td>{pct(row.model_winner_accuracy)}</td><td>{num(row.model_brier)}</td><td>{num(row.baseline_brier)}</td></tr>)}</tbody></table></div></details>}<small>This is a retrospective week-by-week replay, not a record of forecasts archived before kickoff. Positive reductions in error are better. It must not be combined with the separate prospective prediction track record.</small></section>}
      </>}
      {tab === 'methods' && <section className="notice"><h3>Model and historical methods</h3>
        <p>Current forecasts retain the incumbent rating model and game-location adjustment. Model: {report.model_metadata?.model_id || 'Not published'} · status: {report.model_metadata?.model_status || 'Not published'}.</p>
        <p>Home-field setting: {report.model_metadata?.home_field_advantage ?? 'Unavailable'} rating points. Probability scale: {report.model_metadata?.prediction_scale ?? 'Unavailable'}. Playoff simulations: {report.cfp?.methodology || 'Methodology unavailable in this report'}.</p>
        <p>Historical Hype, Trajectory and Report Cards are descriptive peer comparisons, not forecasts. The historical views retain their detailed definitions, national coverage, source records and exceptions. Missing evidence remains N/A.</p>
        <ul><li><a href="https://github.com/landrumc16/College-Football-Analytics/blob/main/docs/V5-HISTORICAL-EVIDENCE.md" target="_blank" rel="noreferrer">Historical methods, sources and limitations</a></li><li><a href="https://github.com/landrumc16/College-Football-Analytics/blob/main/docs/V5-PREDICTION-PERFORMANCE-EVIDENCE.md" target="_blank" rel="noreferrer">Forecast verification methodology</a></li></ul>
      </section>}
      {tab === 'sources' && <><section className="notice"><h3>Published data and provenance</h3><p>Current report: {report.source || 'Source unavailable'}. Retrieved: {report.retrieved_at || 'Not published'}. Last game-data change: {report.data_changed_at || 'Not published'}.</p><p>Historical inputs and accepted exceptions are retained in the verified archive. Source details also accompany each historical table and Report Card.</p><p><a href="https://github.com/landrumc16/College-Football-Analytics/tree/main/research/archive/verified" target="_blank" rel="noreferrer">Retained verified historical archive</a></p></section><details className="research-topic"><summary>Public Poll Comparisons</summary>{pollSnapshot ? <section className="accuracy-summary" aria-label="AP Coaches and CFP Poll Comparison"><strong>AP / Coaches / CFP Poll Comparison · Week {pollSnapshot.week}</strong><p>Published poll positions alongside current model rankings. Poll week and model snapshot may differ; this is not a historical accuracy test. CFP rankings appear only when a verified snapshot is supplied.</p><div className="table-wrap"><table><thead><tr><th>School</th><th>Model</th><th>AP</th><th>Coaches</th><th>CFP</th></tr></thead><tbody>{[...new Set([...pollSnapshot.ap_top25, ...pollSnapshot.coaches_top25, ...(pollSnapshot.cfp_top25 || [])].map(row => row.team))].map(team => <tr key={team}><td>{team}</td><td>{report.rankings.find(r => r.team === team)?.rank ?? '—'}</td><td>{pollSnapshot.ap_top25.find(r => r.team === team)?.rank ?? '—'}</td><td>{pollSnapshot.coaches_top25.find(r => r.team === team)?.rank ?? '—'}</td><td>{pollSnapshot.cfp_top25?.find(r => r.team === team)?.rank ?? '—'}</td></tr>)}</tbody></table></div><small>Source: {pollSnapshot.source}. Missing CFP entries and unmatched school names are shown as —; no inferred matches are made.</small></section> : pollUnavailable && <section className="accuracy-summary" aria-label="Poll comparison availability"><strong>Public poll comparison unavailable</strong><p>No verified AP / Coaches / CFP poll snapshot has been published for this dashboard. Poll rankings are not inferred from the model.</p></section>}
</details></>}
      </section>}
      {(tab === 'ap' || tab === 'coaches') && <section className="notice"><h2>Poll Comparison</h2><p>Our Model vs. AP, Coaches and CFP Top 25. A dash means the school is not listed in that poll or has no verified matching entry. These are rankings, not predictions of future poll positions.</p>{pollSnapshot ? <><p>Poll season {pollSnapshot.season} · Week {pollSnapshot.week} · Source: {pollSnapshot.source}. Model and poll snapshots may have different dates.</p><div className="table-wrap"><table><thead><tr><th>School</th>{([['model', 'Our Model'], ['ap', 'AP'], ['coaches', 'Coaches'], ['cfp', 'CFP']] as const).map(([key, label]) => <th key={key}><button type="button" className="poll-sort-button" aria-label={`Sort by ${label} ranking`} aria-pressed={pollSort === key} onClick={() => setPollSort(key)}>{label}{pollSort === key ? ' ↑' : ''}</button></th>)}</tr></thead><tbody>{[...new Set([...report.rankings.slice(0, 30).map(t => t.team), ...pollSnapshot.ap_top25.map(t => t.team), ...pollSnapshot.coaches_top25.map(t => t.team), ...(pollSnapshot.cfp_top25 || []).map(t => t.team)])].map(team => ({ team, model: report.rankings.find(t => t.team === team)?.rank ?? null, ap: pollSnapshot.ap_top25.find(t => t.team === team)?.rank ?? null, coaches: pollSnapshot.coaches_top25.find(t => t.team === team)?.rank ?? null, cfp: pollSnapshot.cfp_top25?.find(t => t.team === team)?.rank ?? null })).sort((a, b) => (a[pollSort] ?? Infinity) - (b[pollSort] ?? Infinity) || (a.model ?? Infinity) - (b.model ?? Infinity) || a.team.localeCompare(b.team)).slice(0, 30).map(row => <tr key={row.team}><td className="team">{row.team}</td><td>{row.model ?? '—'}</td><td>{row.ap ?? '—'}</td><td>{row.coaches ?? '—'}</td><td>{row.cfp ?? '—'}</td></tr>)}</tbody></table></div><small>Click a ranking column to sort 1–25 (or 1–30 for Our Model). The selected poll's ranked teams appear first, followed by other schools for comparison, up to 30 total. CFP is blank until its independently verified poll is available. Unmatched school names are not silently merged.</small></> : <p role="status">Verified AP and Coaches Poll data is unavailable. Public poll rankings are not inferred from our model.</p>}</section>}
      {/* Conference membership reflects the current standings snapshot, not historical realignment. */}
      {(['programs', 'hype', 'trajectory', 'stock', 'contenders'] as const).includes(tab as 'programs') && <ProgramIntelligence view={tab === 'hype' ? 'hype' : tab === 'trajectory' ? 'trajectory' : tab === 'stock' ? 'stock' : tab === 'contenders' ? 'contenders' : 'overview'} currentPoll={pollSnapshot} currentRankings={report.rankings} currentSeason={report.season} conferenceStandings={report.conference_standings || {}} schedule={report.schedule || []} performance={report.performance || {}} postseason={report.cfp?.teams || []} conferenceTeams={Object.fromEntries(Object.entries(report.conference_standings || {}).map(([name, entries]) => [name, entries.map(entry => entry.team)]))} onTeam={team => { setScheduleTeam(team); setTab('profile') }} onCompare={openComparison} />}
      {tab === 'profile' && <TeamProfile team={selectedScheduleTeam} rankings={report.rankings} poll={pollSnapshot} cfp={report.cfp?.teams || []} schedule={report.schedule || []} predictions={report.predictions} recruiting={recruitingResearch?.program_recruiting_residuals?.programs || []} performance={report.performance || {}} conferences={report.conference_standings || {}} modelMetadata={report.model_metadata} section={profileSection} onSection={setProfileSection} scheduleContent={schoolSchedule} onChoose={setScheduleTeam} onCompare={openComparison} />}
      {tab === 'compare' && <section className="matchup-panel"><h2>Compare Teams</h2><p>{tab === 'compare' ? 'Compare the current published model metrics for two schools side by side. Select both schools to see the comparison; the matchup projection below uses the selected game location.' : "Choose two schools and a game location to see the model's predicted winner, margin, and win probability."}</p><div className="matchup-inputs"><label>School 1<select aria-label="First school" value={homeTeam} onChange={e => setHomeTeam(e.target.value)}><option value="">Select School</option>{sortedTeams.map(t => <option key={t.team} value={t.team}>{t.team}</option>)}</select></label><label>School 2<select aria-label="Second school" value={awayTeam} onChange={e => setAwayTeam(e.target.value)}><option value="">Select School</option>{sortedTeams.map(t => <option key={t.team} value={t.team}>{t.team}</option>)}</select></label><label>Game location<select aria-label="Game location" value={venue} onChange={e => setVenue(e.target.value as 'home' | 'away' | 'neutral')}><option value="home">At School 1</option><option value="away">At School 2</option><option value="neutral">Neutral Site</option></select></label></div>{tab === 'compare' && selectedHome && selectedAway && homeTeam !== awayTeam && <section aria-label="Side-by-side team comparison" className="notice"><h3>Side-by-side team comparison</h3><div className="report-card-comparison"><ProgramReportCard team={selectedHome.team} /><ProgramReportCard team={selectedAway.team} /></div><HistoricalResults team={selectedHome.team} compareTeam={selectedAway.team} onTeam={team => {setScheduleTeam(team);setTab("profile")}} /><p>Current-season incumbent model data. Rankings and projected wins are not historical program trajectories.</p><div className="table-wrap"><table><thead><tr><th scope="col">Metric</th><th scope="col">{selectedHome.team}</th><th scope="col">{selectedAway.team}</th></tr></thead><tbody><tr><th scope="row">Model rank</th><td>#{selectedHome.rank}</td><td>#{selectedAway.rank}</td></tr><tr><th scope="row">Strength rating</th><td>{num(selectedHome.rating)}</td><td>{num(selectedAway.rating)}</td></tr><tr><th scope="row">Record</th><td>{selectedHome.wins}–{selectedHome.losses}</td><td>{selectedAway.wins}–{selectedAway.losses}</td></tr><tr><th scope="row">Projected wins</th><td>{num(selectedHome.projected_wins)}</td><td>{num(selectedAway.projected_wins)}</td></tr><tr><th scope="row">CFP qualification chance</th><td>{report.cfp?.teams.find(t => t.team === selectedHome.team)?.cfp_field != null ? pct(report.cfp.teams.find(t => t.team === selectedHome.team)!.cfp_field) : 'Unavailable'}</td><td>{report.cfp?.teams.find(t => t.team === selectedAway.team)?.cfp_field != null ? pct(report.cfp.teams.find(t => t.team === selectedAway.team)!.cfp_field) : 'Unavailable'}</td></tr></tbody></table></div><p><button type="button" onClick={() => {setScheduleTeam(selectedHome.team);setTab('profile')}}>View {selectedHome.team} profile</button> <button type="button" onClick={() => {setScheduleTeam(selectedAway.team);setTab('profile')}}>View {selectedAway.team} profile</button></p></section>}<div className="matchup-actions"><button type="button" onClick={() => { setHomeTeam(awayTeam); setAwayTeam(homeTeam) }}>Swap schools</button><button type="button" onClick={() => { setHomeTeam(""); setAwayTeam(""); setVenue("home") }}>Reset matchup</button></div>{homeTeam && homeTeam === awayTeam && <p role="alert">Choose two different schools.</p>}{matchup && <div className="matchup-result" aria-live="polite"><small>MODEL PROJECTED WINNER</small><h3>{matchup.winner}</h3><strong>{matchup.confidence} · {num(Math.abs(matchup.margin))}-point projected margin</strong><div className="matchup-odds"><div><span>{actualHome!.team}</span><strong>{pct(matchup.homeProbability)}</strong></div><div><span>{actualAway!.team}</span><strong>{pct(1 - matchup.homeProbability)}</strong></div></div><p>{venue === 'neutral' ? 'Neutral Site: no home-field advantage' : `Home: ${actualHome!.team} (+3-point home-field advantage)`} · Ratings from the current published season report. Probabilities are estimates, not guarantees.</p></div>}</section>}
      {tab === 'predictions' && <section className="predictions-intro"><h2>Game Predictions</h2><p>Showing {sortedPredictions.length} remaining FBS matchup{sortedPredictions.length === 1 ? '' : 's'}{search.trim() ? ' matching your search across all upcoming weeks' : ''}. Select a week or search for a school. Win probabilities are estimates, not guarantees.</p></section>}
      {tab === 'cfp' && <section className="predictions-intro"><h2>Our Top 25 vs. Official CFP Top 25</h2><p>Our Top 25 uses the existing model rankings. {pollSnapshot?.cfp_top25?.length && pollSnapshot.season === report.season && pollSnapshot.cfp_published_at ? `Official CFP snapshot: ${pollSnapshot.season}, CFP poll week ${pollSnapshot.cfp_week ?? 'unavailable'} · Source: ${pollSnapshot.cfp_source ? 'College Football Playoff' : pollSnapshot.source}. Published: ${pollSnapshot.cfp_published_at}. The model and committee snapshots may differ.` : 'A verified, publication-dated official CFP Top 25 is not available in the published poll snapshot. Official rank and difference remain unavailable.'}</p><div className="table-wrap"><table><thead><tr><th>Team</th><th>Our rank</th><th>Official CFP rank</th><th>Difference</th></tr></thead><tbody>{(() => { const modelTop=[...report.rankings].sort((a,b)=>a.rank-b.rank).slice(0,25); const official=pollSnapshot?.season===report.season && pollSnapshot.cfp_published_at ? (pollSnapshot.cfp_top25 || []) : []; const key=(name:string)=>name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,''); const officialByKey=new Map(official.map(t=>[key(t.team),t])); const modelKeys=new Set(modelTop.map(t=>key(t.team))); const rows=[...modelTop.map(t=>({team:t.team,ours:t.rank,committee:officialByKey.get(key(t.team))?.rank})),...official.filter(t=>!modelKeys.has(key(t.team))).map(t=>({team:t.team,ours:report.rankings.find(r=>key(r.team)===key(t.team))?.rank,committee:t.rank}))]; return rows.map(t=><tr key={t.team}><td>{t.team}</td><td>{t.ours ? '#'+t.ours : 'Unranked'}</td><td>{t.committee ? '#'+t.committee : official.length ? 'Unranked' : 'Unavailable'}</td><td>{t.ours && t.committee ? (t.committee-t.ours>0?'+':'')+(t.committee-t.ours) : '—'}</td></tr>) })()}</tbody></table></div><small>Difference = official rank minus our rank; positive means our model ranks the team higher. Unranked means outside that Top 25, not a missing official release. Exact normalized team names are matched; ambiguous aliases are not inferred.</small></section>}
      {tab === 'cfp' && <section className="predictions-intro"><h2>Playoff Bubble</h2><p>Teams outside the projected 12-team field with the highest simulated qualification chances. These are model estimates, not committee rankings.</p>{report.cfp?.teams?.length ? <div className="table-wrap"><table><thead><tr><th>Team</th><th>Model rank</th><th>Playoff chance</th></tr></thead><tbody>{report.cfp.teams.filter(t=>!bracketByTeam.has(t.team)).sort((a,b)=>b.cfp_field-a.cfp_field).slice(0,8).map(t=><tr key={t.team}><td>{t.team}</td><td>{report.rankings.find(r=>r.team===t.team)?.rank ?? '—'}</td><td>{pct(t.cfp_field)}</td></tr>)}</tbody></table></div> : <p>Simulation probabilities are unavailable in this report.</p>}<h2>Games That Matter</h2><p>Upcoming games involving the model's Top 25 or projected playoff teams. Stakes are descriptive; no exact ranking changes are forecast.</p>{futurePredictions.filter(p=>{const h=report.rankings.find(t=>t.team===p.home)?.rank??999,a=report.rankings.find(t=>t.team===p.away)?.rank??999;return h<=25||a<=25||bracketByTeam.has(p.home)||bracketByTeam.has(p.away)}).sort((a,b)=>a.week-b.week||Math.min(report.rankings.find(t=>t.team===a.home)?.rank??999,report.rankings.find(t=>t.team===a.away)?.rank??999)-Math.min(report.rankings.find(t=>t.team===b.home)?.rank??999,report.rankings.find(t=>t.team===b.away)?.rank??999)).slice(0,6).map(p=><button key={p.game_id} type="button" className="weekly-game" onClick={()=>{setSearch(p.home);setWeek(String(p.week));setTab('predictions')}}><strong>{rankedName(p.away)} at {rankedName(p.home)}</strong><span>Week {p.week} · {bracketByTeam.has(p.home)||bracketByTeam.has(p.away)?'Projected playoff contender in action':'Top-25 team in action'} · {pct(Math.max(p.home_win_probability,1-p.home_win_probability))} for {p.predicted_winner}</span></button>)}{!futurePredictions.some(p=>bracketByTeam.has(p.home)||bracketByTeam.has(p.away)||(report.rankings.find(t=>t.team===p.home)?.rank??999)<=25||(report.rankings.find(t=>t.team===p.away)?.rank??999)<=25)&&<p>No qualifying upcoming games in the published schedule.</p>}</section>}
      {tab === 'cfp' && <section className="predictions-intro"><h2>Projected 12-Team CFP Field</h2><p>Unique bracket seeds appear below. The simulation table shows each team's chance to qualify; a team's most frequent simulated seed is not its current bracket rank.</p></section>}
      {tab === 'cfp' && report.projected_bracket && <section className="bracket-grid" aria-label="Projected 12-Team CFP Bracket">{[...report.projected_bracket.seeds].sort((a,b) => a.seed - b.seed).map(s => <article key={s.seed} className="bracket-team"><span className="bracket-seed">#{s.seed}</span><div><strong>{s.team}</strong><small>{s.conference} · {s.bid === 'automatic' ? 'Automatic Bid' : 'At-Large'}{s.bye ? ' · First-Round Bye' : ''}</small></div></article>)}</section>}
      {(['rankings', 'predictions', 'conferences', 'cfp'] as string[]).includes(tab) && <div className="table-wrap">{tab === 'rankings' ? <table><thead><tr><th>Team / rank</th><th>Record</th><th>Rating</th><th>Projected wins</th><th>Conf. wins</th><th>Rank drivers</th><th>Actions</th></tr></thead><tbody>{teams.map(t => <tr key={t.team}><td className="team"><span className="team-number">#{t.rank}</span>{t.team}</td><td>{t.wins}–{t.losses}</td><td>{num(t.rating)}</td><td className="emphasis">{num(t.projected_wins)}</td><td>{num(t.projected_conference_wins)}</td><td>{t.ranking_explanation ? <details><summary>Explain</summary><small>Projected wins: {num(t.ranking_explanation.wins_contribution)} · Rating: {num(t.ranking_explanation.rating_contribution)} · Tie-break: {t.ranking_explanation.tie_break_contribution.toExponential(1)} · Score: {num(t.ranking_explanation.score)}. {t.ranking_explanation.scope}</small></details> : <small>Unavailable</small>}</td><td><button type="button" onClick={() => {setScheduleTeam(t.team);setTab('profile')}} aria-label={`View ${t.team} profile`}>View team</button> <button type="button" onClick={() => openComparison(t.team)} aria-label={`Compare ${t.team} with another school`}>Compare</button></td></tr>)}</tbody></table> : tab === 'predictions' ? <div className="prediction-cards">{sortedPredictions.map(p => { const winnerProb = p.predicted_winner === p.home ? p.home_win_probability : 1 - p.home_win_probability; return <article key={p.game_id} className="prediction-card"><div className="prediction-meta">WEEK {p.week} · {p.confidence.toUpperCase()}</div><div className="prediction-matchup"><span>{p.away}</span><span className="prediction-at">@</span><span>{p.home}</span></div><div className="prediction-pick"><span>Predicted Winner</span><strong>{p.predicted_winner}</strong></div><div className="prediction-metrics"><div><small>Win Probability</small><strong>{pct(winnerProb)}</strong></div><div><small>Projected Margin</small><strong>{num(Math.abs(p.home_margin))} pts</strong></div></div><details className="pick-explanation"><summary>Why this pick?</summary><p>The model projects {p.predicted_winner} by {num(Math.abs(p.home_margin))} points, with a {pct(winnerProb)} chance to win. This forecast uses the existing team ratings and game-location adjustment; it is not a guarantee.</p></details><div className="prediction-actions"><button type="button" onClick={() => void sharePrediction(p)}>Share prediction</button><button type="button" onClick={() => {setHomeTeam(p.home);setAwayTeam(p.away);setVenue('home');setTab('compare')}}>Compare teams</button></div></article>})}{sortedPredictions.length === 0 && <p>No upcoming matchups match these filters.</p>}</div> : tab === 'conferences' ? <table><thead><tr><th>Team</th><th>Conf. record</th><th>Overall</th><th>Rating</th><th>Projected conf. wins</th><th>Title odds</th><th>CFP odds</th></tr></thead><tbody>{conferenceRows.map(t => <tr key={t.team}><td className="team">{t.team}</td><td>{t.conference_wins}–{t.conference_losses}</td><td>{t.wins}–{t.losses}</td><td>{num(t.rating)}</td><td>{num(t.projected_conference_wins)}</td><td>{pct(t.conference_title_odds)}</td><td>{pct(t.cfp_odds)}</td></tr>)}</tbody></table> : <table><thead><tr><th>Team</th><th>Conference</th><th>Avg wins</th><th>80% wins range</th><th>Bowl eligible</th><th>CFP field</th><th>Avg Seed If Selected</th><th>Bye</th><th>Quarterfinal</th><th>Semifinal</th><th>Final</th><th>National title</th></tr></thead><tbody>{cfpRows.map(t => <tr key={t.team}><td className="team">{t.team}{bracketByTeam.get(t.team)?.bid === "automatic" && <span className="auto-bid" title="Projected automatic CFP qualifier" aria-label="Projected automatic CFP qualifier">A</span>}</td><td>{t.conference}</td><td>{num(t.average_wins)}</td><td>{t.wins_p10}–{t.wins_p90}</td><td>{pct(t.bowl_eligible)}</td><td>{pct(t.cfp_field)}</td><td>{t.average_seed_when_selected == null ? "—" : num(t.average_seed_when_selected)}</td><td>{pct(t.first_round_bye)}</td><td>{pct(t.quarterfinal)}</td><td>{pct(t.semifinal)}</td><td>{pct(t.final)}</td><td className="emphasis">{pct(t.national_title)}</td></tr>)}</tbody></table>}</div>}
      {tab === 'cfp' && report.projected_bracket && <section className="notice"><h2>Bracket Details</h2><p>{report.projected_bracket.methodology}</p><p><span className="auto-bid">A</span> Projected automatic qualifier · Other teams receive at-large bids. These are model projections, not official CFP selections.</p><div className="table-wrap"><table><thead><tr><th>Seed / team</th><th>Conference</th><th>Bid</th><th>First round</th></tr></thead><tbody>{report.projected_bracket.seeds.map(s => <tr key={s.seed}><td className="team"><span className="team-number">#{s.seed}</span>{s.team}{s.bid === "automatic" && <span className="auto-bid" title="Projected automatic CFP qualifier">A</span>}</td><td>{s.conference}</td><td>{s.bid === 'automatic' ? 'Automatic' : 'At-large'}</td><td>{s.bye ? 'Bye' : 'Plays'}</td></tr>)}</tbody></table></div><h3>Opening-Round Matchups</h3><div className="table-wrap"><table><thead><tr><th>Higher seed</th><th>Lower seed</th></tr></thead><tbody>{report.projected_bracket.first_round.map(m => <tr key={m.home_seed}><td className="team"><span className="team-number">#{m.home_seed}</span>{m.home}</td><td className="team"><span className="team-number">#{m.away_seed}</span>{m.away}</td></tr>)}</tbody></table></div></section>}
      {tab === 'conferences' && !!report.projected_bracket?.conference_championships?.length && <><h2>Projected Conference Championship Games</h2><div className="table-wrap"><table><thead><tr><th>Conference</th><th>Projected finalists</th><th>Model favorite</th></tr></thead><tbody>{report.projected_bracket.conference_championships.filter(m => selectedConference === m.conference).map(m => <tr key={m.conference}><td className="team">{m.conference}</td><td>{m.first} vs {m.second}</td><td className="emphasis">{m.projected_champion}</td></tr>)}</tbody></table></div></>}
      {tab === 'cfp' && <section className="notice"><strong>{report.cfp?.simulations?.toLocaleString() || 'No'} CFP simulations</strong><p>{report.cfp?.methodology || 'Rebuild the season report to enable CFP Forecasting.'}</p></section>}
      {tab === 'conferences' && !!report.conference_strength?.length && <><h2>Conference Strength</h2><div className="table-wrap"><table><thead><tr><th>Conference</th><th>Teams</th><th>Average rating</th><th>Best team</th></tr></thead><tbody>{report.conference_strength.map(c => <tr key={c.conference}><td className="team">{c.conference}</td><td>{c.teams}</td><td>{num(c.average_rating)}</td><td>{c.best_team}</td></tr>)}</tbody></table></div></>}
      </div><footer>Model estimates are probabilistic, not guarantees. Data source: {report.source || 'CFBD'}. {report.retrieved_at ? `Last successful data check: ${new Date(report.retrieved_at).toLocaleString()}.` : 'Historical fixture or retrieval date unavailable.'} {report.data_changed_at ? `Game data last changed: ${new Date(report.data_changed_at).toLocaleString()}.` : ''}</footer>
    </>}
  </main>
}

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => { navigator.serviceWorker.register(import.meta.env.BASE_URL + 'sw.js', { scope: import.meta.env.BASE_URL }).catch(() => { /* App remains usable in browser without service worker. */ }) })
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App /></React.StrictMode>)
